from griffe import Extension, Extensions, load


class DocstringCheckerExtension(Extension):
    """Extension that appends ' [checked]' to every function's docstring."""

    def on_function(self, func, **kwargs):
        """Append ' [checked]' to the function's docstring."""
        if func.docstring is not None:
            func.docstring.value += " [checked]"
        else:
            # If no docstring exists, create one with just "[checked]"
            from griffe import Docstring
            func.docstring = Docstring("[checked]", lineno=0, endlineno=0)


# Create the extension instance
extension = DocstringCheckerExtension()

# Aggregate the extension into an Extensions container
extensions = Extensions(extension)

# Load the package with the extension enabled
module = load("mypkg", extensions=extensions)

# Print the results
if hasattr(module, "functions"):
    for func in module.functions:
        print(f"{func.name}: {func.docstring.value if func.docstring else 'None'}")

